  it("copies a historical successful result through the shared Markdown formatter", async () => { vi.mocked(loadSpecialistRuns).mockResolvedValue({ formatVersion: 1, projectId: workspace.projectId, updatedAt: "2026-09-19T12:00:00Z", runs: [successfulRun] }); const user = await renderPage(); const clipboardWrite = vi.spyOn(navigator.clipboard, "writeText"); await user.click(screen.getByRole("button", { name: "Copy Result as Markdown" })); const markdown = clipboardWrite.mock.calls[0][0]; expect(markdown).toContain("# AI Behavior Designer — REACTION_MODEL"); expect(markdown).toContain("- Timestamp: 2026-09-19T12:00:00Z"); expect(markdown).toContain("- Compendium: Imperfect information"); expect(markdown).toContain("- Approved Decision: No omniscience"); });
  it("lists failed runs with safe categories and diagnostics", async () => { vi.mocked(loadSpecialistRuns).mockResolvedValue({ formatVersion: 1, projectId: workspace.projectId, updatedAt: "2026-09-19T12:05:00Z", runs: [failedRun] }); await renderPage(); const alert = screen.getByRole("alert"); expect(alert).toHaveTextContent("OUTPUT_TRUNCATED"); expect(alert).toHaveTextContent("length"); expect(alert).not.toHaveTextContent("raw response"); });
  it("keeps failed scenarios reusable and exports only safe stored diagnostics as Markdown", async () => { vi.mocked(loadSpecialistRuns).mockResolvedValue({ formatVersion: 1, projectId: workspace.projectId, updatedAt: "2026-09-19T12:05:00Z", runs: [failedRun] }); const user = await renderPage(); const clipboardWrite = vi.spyOn(navigator.clipboard, "writeText"); const detail = screen.getByLabelText("Selected historical run"); expect(within(detail).getByLabelText("Scenario / Question")).toHaveTextContent(failedRun.scenario); expect(within(detail).getByRole("button", { name: "Copy Scenario" })).toBeInTheDocument(); const copy = within(detail).getByRole("button", { name: "Copy Run Diagnostics as Markdown" }); await user.click(copy); await waitFor(() => expect(clipboardWrite).toHaveBeenCalledTimes(1)); const markdown = clipboardWrite.mock.calls[0][0]; expect(markdown).toContain("# AI Behavior Designer Diagnostics - REACTION_MODEL"); expect(markdown).toContain(failedRun.scenario); expect(markdown).toContain("OUTPUT_TRUNCATED"); expect(markdown).toContain("Finish reason: length"); expect(markdown).not.toContain("raw response"); expect(within(copy.closest<HTMLElement>(".specialist-copy-control")!).getByRole("status")).toHaveTextContent("Copied"); });
  it("lets the user switch between prior successful and failed runs", async () => { vi.mocked(loadSpecialistRuns).mockResolvedValue({ formatVersion: 1, projectId: workspace.projectId, updatedAt: "2026-09-19T12:05:00Z", runs: [successfulRun, failedRun] }); const user = await renderPage(); expect(screen.getByRole("alert")).toHaveTextContent("OUTPUT_TRUNCATED"); await user.click(screen.getByRole("button", { name: /REACTION_MODEL.*SUCCEEDED/s })); expect(within(screen.getByRole("heading", { name: "Analysis Result" }).closest("section")!).getByText(analysis.result.summary)).toBeInTheDocument(); expect(screen.queryByRole("alert")).not.toBeInTheDocument(); });
  it("refreshes history after a completed run", async () => { vi.mocked(loadSpecialistRuns).mockResolvedValueOnce(null).mockResolvedValueOnce({ formatVersion: 1, projectId: workspace.projectId, updatedAt: "2026-09-19T12:00:00Z", runs: [successfulRun] }); const user = await renderPage(); await fillAndRun(user); await waitFor(() => expect(loadSpecialistRuns).toHaveBeenCalledTimes(2)); expect(screen.getByRole("button", { name: /REACTION_MODEL.*SUCCEEDED/s })).toHaveAttribute("aria-current", "true"); });
